<script lang="ts" setup>
import { computed, onMounted, ref } from 'vue';
import { Page } from '@vben/common-ui';
import { message } from 'ant-design-vue';
import { getCloudServiceAssetList } from '#/api/scan/cloud-service-asset';
import { getCloudProviderConfigList, syncCloudInstances } from '#/api/scan/cloud-provider-config';

interface Asset { id:string;provider_config_id:number;provider:string;account_name:string;name:string;instance_id:string;asset_type:string;source_type:string;status:string;cloud_platform:string;cloud_zone:string;region?:string;region_id?:string;availability_zone?:string;instance_type:string;cpu_cores:number;memory_gb:number;system_disk_type:string;system_disk_size_gb:number;ip_address:string;public_ip?:string;os_name:string;customer_name:string;created_at:string;updated_at?:string; }
const data=ref<Asset[]>([]),loading=ref(false),searchText=ref(''),configs=ref<any[]>([]),selectedConfigId=ref<number>(),syncing=ref(false);
const detailVisible=ref(false),detailAsset=ref<Asset>();
const columns=[{title:'实例',key:'instance',width:220,fixed:'left'},{title:'状态',key:'status',width:90},{title:'云平台 / 厂商',key:'platform',width:180},{title:'对接账号',dataIndex:'account_name',width:150},{title:'资源区 / 地域',key:'location',width:190},{title:'规格',key:'spec',width:160},{title:'网络',key:'network',width:150},{title:'系统',dataIndex:'os_name',width:150,ellipsis:true},{title:'客户',dataIndex:'customer_name',width:120},{title:'同步时间',key:'sync_time',width:170},{title:'操作',key:'actions',width:80,fixed:'right'}];
const typeLabel:Record<string,string>={cloud:'云虚拟机',virtual:'云虚拟机'};
const providerLabel:Record<string,string>={aliyun:'阿里云',huawei:'华为云',tencent:'腾讯云',hcs:'华为云 Stack',openstack:'OpenStack'};
const visibleRows=computed(()=>{const keyword=searchText.value.trim().toLowerCase();if(!keyword)return data.value;return data.value.filter(row=>[row.name,row.instance_id,row.provider,row.account_name,row.cloud_platform,row.cloud_zone,row.region,row.availability_zone,row.ip_address,row.customer_name].some(value=>String(value??'').toLowerCase().includes(keyword)));});
async function fetchData(){loading.value=true;try{const [assetRows,configRows]=await Promise.all([getCloudServiceAssetList(),getCloudProviderConfigList()]);data.value=assetRows as any;configs.value=configRows as any;if(!selectedConfigId.value&&configs.value.length)selectedConfigId.value=configs.value[0].id;}catch{message.error('加载失败');}finally{loading.value=false;}}
async function handleSync(){if(!selectedConfigId.value){message.warning('请先选择云厂商对接配置');return;}syncing.value=true;const hide=message.loading({content:'正在从云厂商同步实例...',duration:0});try{await syncCloudInstances(selectedConfigId.value);hide();message.success('云资源实例同步完成');await fetchData();}catch{hide();message.error('同步失败，请检查对接配置和连接状态');}finally{syncing.value=false;}}
function showDetail(asset:Asset){detailAsset.value=asset;detailVisible.value=true;}
onMounted(fetchData);
</script>
<template><Page auto-content-height><div style="padding:16px"><a-page-header title="云资源实例" sub-title="统一查看通过云厂商接口同步的计算实例及其平台归属" style="margin-bottom:16px;padding:0"/><div class="resource-toolbar"><a-space :size="20"><a-select v-model:value="selectedConfigId" :options="configs.map(config=>({value:config.id,label:`${config.account_name} / ${config.region_name}`}))" placeholder="选择云厂商对接配置" style="width:280px"/><a-button type="primary" :loading="syncing" @click="handleSync">同步云资源实例</a-button></a-space><a-space :size="20"><a-input-search v-model:value="searchText" allow-clear placeholder="搜索实例、账号、地域、IP 或客户" style="width:300px"/><a-button :loading="loading" @click="fetchData">刷新</a-button></a-space></div><a-table :columns="columns" :data-source="visibleRows" :loading="loading" row-key="id" size="middle" :pagination="{pageSize:20}" :scroll="{x:1700}"><template #bodyCell="{column,record}"><template v-if="column.key==='instance'"><div class="instance-name">{{record.name}}</div><div class="instance-id">{{record.instance_id||'-'}} · {{typeLabel[record.asset_type]||record.asset_type}}</div></template><template v-else-if="column.key==='platform'"><div>{{record.cloud_platform}}</div><div class="secondary-text">{{providerLabel[record.provider]||record.provider}}</div></template><template v-else-if="column.key==='location'"><div>{{record.cloud_zone||'-'}} / {{record.region||record.region_id||'-'}}</div><div v-if="record.availability_zone" class="secondary-text">可用区：{{record.availability_zone}}</div></template><template v-else-if="column.key==='spec'"><div>{{record.cpu_cores}}核 / {{record.memory_gb}}GB</div><div class="secondary-text">{{record.instance_type||'未识别规格'}}</div></template><template v-else-if="column.key==='network'"><div>{{record.ip_address||'-'}}</div><div v-if="record.public_ip" class="secondary-text">公网 {{record.public_ip}}</div></template><template v-else-if="column.key==='sync_time'">{{record.updated_at||record.created_at}}</template><template v-else-if="column.key==='status'"><a-tag :color="record.status==='运行中'?'green':record.status==='已停止'?'default':'orange'">{{record.status}}</a-tag></template><template v-else-if="column.key==='actions'"><a-button type="link" size="small" @click="showDetail(record)">详情</a-button></template></template></a-table><a-drawer v-model:open="detailVisible" title="云资源实例详情" width="560"><a-descriptions v-if="detailAsset" bordered size="small" :column="1"><a-descriptions-item label="实例名称">{{detailAsset.name}}</a-descriptions-item><a-descriptions-item label="实例 ID">{{detailAsset.instance_id||'-'}}</a-descriptions-item><a-descriptions-item label="云平台">{{detailAsset.cloud_platform}}</a-descriptions-item><a-descriptions-item label="云厂商">{{providerLabel[detailAsset.provider]||detailAsset.provider}}</a-descriptions-item><a-descriptions-item label="对接账号">{{detailAsset.account_name}}</a-descriptions-item><a-descriptions-item label="资源位置">{{detailAsset.cloud_zone}} / {{detailAsset.region||detailAsset.region_id||'-'}} / {{detailAsset.availability_zone||'未返回可用区'}}</a-descriptions-item><a-descriptions-item label="实例规格">{{detailAsset.instance_type||'-'}}（{{detailAsset.cpu_cores}}核 / {{detailAsset.memory_gb}}GB）</a-descriptions-item><a-descriptions-item label="系统盘">{{detailAsset.system_disk_type||'-'}} / {{detailAsset.system_disk_size_gb}}GB</a-descriptions-item><a-descriptions-item label="操作系统">{{detailAsset.os_name||'-'}}</a-descriptions-item><a-descriptions-item label="私网 IP">{{detailAsset.ip_address||'-'}}</a-descriptions-item><a-descriptions-item label="公网 IP">{{detailAsset.public_ip||'-'}}</a-descriptions-item><a-descriptions-item label="客户">{{detailAsset.customer_name||'-'}}</a-descriptions-item><a-descriptions-item label="数据来源">云厂商接口同步</a-descriptions-item><a-descriptions-item label="最后同步">{{detailAsset.updated_at||detailAsset.created_at}}</a-descriptions-item></a-descriptions></a-drawer></div></Page></template>
<style scoped>.resource-toolbar{display:flex;align-items:center;justify-content:space-between;gap:32px;margin-bottom:20px}.instance-name{font-weight:500}.instance-id,.secondary-text{margin-top:3px;color:var(--ant-color-text-secondary);font-size:12px}@media(max-width:900px){.resource-toolbar{align-items:flex-start;flex-direction:column}}</style>
